struct PixelBuf:
    data: *mut u8
    len: usize

unsafe extern "C":
    @safety("`buf.data` points at `buf.len` writable bytes")
    @ffi(no_callbacks)
    unsafe fn clear_pixels(buf: PixelBuf)

fn clear(ref mut bytes: MutSpan[u8]):
    # SAFETY: the struct describes exactly the bytes of `bytes`
    unsafe:
        clear_pixels(PixelBuf(data=bytes.as_mut_ptr(), len=bytes.len() as usize))

fn main():
    frame: Array[u8] = [7, 7, 7, 7]
    clear(ref mut frame)
    println(frame[0], frame[3], frame.len())

