    x: u8 = 7
    clear_pixels(PixelBuf(data=ref_to_ptr(ref mut x), len=4096))

fn make(ref mut frame: Array[u8]) -> PixelBuf:
    # SAFETY: `data` points at the bytes of `frame`
    unsafe:
        return PixelBuf(data=frame.as_mut_span().as_mut_ptr(), len=frame.len() as usize)

